     1→// Phase 2: Integrity Verification System
     2→// 실시간 무결성 검증 및 일관성 스냅샷
     3→
     4→use crate::cas::*;
     5→use std::collections::HashMap;
     6→
     7→/// 무결성 검사 결과
     8→#[derive(Clone, Debug, PartialEq)]
     9→pub enum IntegrityStatus {
    10→    Valid,              // 유효함
    11→    Corrupted,          // 손상됨
    12→    Missing,            // 청크 누락
    13→    Modified,           // 변조됨
    14→    Unknown,            // 미확인
    15→}
    16→
    17→/// 파일 무결성 보고서
    18→#[derive(Clone, Debug)]
    19→pub struct IntegrityReport {
    20→    pub filename: String,
    21→    pub status: IntegrityStatus,
    22→    pub original_hash: String,
    23→    pub computed_hash: String,
    24→    pub checked_at: u64,
    25→    pub chunk_status: Vec<ChunkStatus>,
    26→}
    27→
    28→/// 청크 상태
    29→#[derive(Clone, Debug, PartialEq)]
    30→pub struct ChunkStatus {
    31→    pub index: usize,
    32→    pub hash: String,
    33→    pub status: IntegrityStatus,
    34→}
    35→
    36→/// 일관성 스냅샷 (특정 시점의 전체 시스템 상태)
    37→#[derive(Clone, Debug)]
    38→pub struct ConsistencySnapshot {
    39→    pub timestamp: u64,
    40→    pub total_files: usize,
    41→    pub valid_files: usize,
    42→    pub corrupted_files: usize,
    43→    pub file_reports: Vec<IntegrityReport>,
    44→    pub overall_health: f64,  // 0.0 ~ 1.0 (1.0 = 완벽)
    45→}
    46→
    47→/// 무결성 검증 엔진
    48→pub struct IntegrityChecker {
    49→    // 파일명 → 최근 검증 보고서
    50→    last_reports: HashMap<String, IntegrityReport>,
    51→    // 스냅샷 이력
    52→    snapshots: Vec<ConsistencySnapshot>,
    53→    total_checks: usize,
    54→    total_corruptions_detected: usize,
    55→}
    56→
    57→impl IntegrityChecker {
    58→    pub fn new() -> Self {
    59→        IntegrityChecker {
    60→            last_reports: HashMap::new(),
    61→            snapshots: Vec::new(),
    62→            total_checks: 0,
    63→            total_corruptions_detected: 0,
    64→        }
    65→    }
    66→
    67→    /// 파일 무결성 검증
    68→    pub fn verify_file(&mut self, filename: &str, manifest: &FileManifest, store: &ChunkStore) -> IntegrityReport {
    69→        self.total_checks += 1;
    70→        let mut reconstructed = Vec::new();
    71→        let mut chunk_statuses = Vec::new();
    72→        let mut all_valid = true;
    73→
    74→        // 모든 청크 검증
    75→        for (idx, chunk_hash) in manifest.chunk_hashes.iter().enumerate() {
    76→            let chunk_opt = store.get_chunk(chunk_hash);
    77→
    78→            if let Some(chunk) = chunk_opt {
    79→                // 청크 존재: 유효함
    80→                reconstructed.extend_from_slice(&chunk);
    81→                chunk_statuses.push(ChunkStatus {
    82→                    index: idx,
    83→                    hash: chunk_hash.to_hex(),
    84→                    status: IntegrityStatus::Valid,
    85→                });
    86→            } else {
    87→                // 청크 누락
    88→                all_valid = false;
    89→                chunk_statuses.push(ChunkStatus {
    90→                    index: idx,
    91→                    hash: chunk_hash.to_hex(),
    92→                    status: IntegrityStatus::Missing,
    93→                });
    94→            }
    95→        }
    96→
    97→        // 파일 크기 조정
    98→        reconstructed.truncate(manifest.file_size);
    99→
   100→        // 파일 해시 재계산
   101→        let engine = HashEngine::new();
   102→        let computed_hash = engine.sha256(&reconstructed);
   103→        let original_hash = &manifest.file_hash;
   104→
   105→        // 무결성 판정
   106→        let status = if !all_valid {
   107→            IntegrityStatus::Missing
   108→        } else if computed_hash == *original_hash {
   109→            IntegrityStatus::Valid
   110→        } else {
   111→            IntegrityStatus::Modified
   112→        };
   113→
   114→        if status != IntegrityStatus::Valid {
   115→            self.total_corruptions_detected += 1;
   116→        }
   117→
   118→        let report = IntegrityReport {
   119→            filename: filename.to_string(),
   120→            status: status.clone(),
   121→            original_hash: original_hash.to_hex(),
   122→            computed_hash: computed_hash.to_hex(),
   123→            checked_at: self.current_timestamp(),
   124→            chunk_status: chunk_statuses,
   125→        };
   126→
   127→        self.last_reports.insert(filename.to_string(), report.clone());
   128→        report
   129→    }
   130→
   131→    /// 특정 파일의 최근 보고서 조회
   132→    pub fn get_last_report(&self, filename: &str) -> Option<IntegrityReport> {
   133→        self.last_reports.get(filename).cloned()
   134→    }
   135→
   136→    /// 일관성 스냅샷 생성
   137→    pub fn create_snapshot(&mut self, manifests: &HashMap<String, FileManifest>, store: &ChunkStore) -> ConsistencySnapshot {
   138→        let total_files = manifests.len();
   139→        let mut valid_count = 0;
   140→        let mut corrupted_count = 0;
   141→        let mut reports = Vec::new();
   142→
   143→        for (filename, manifest) in manifests {
   144→            let report = self.verify_file(filename, manifest, store);
   145→
   146→            match report.status {
   147→                IntegrityStatus::Valid => valid_count += 1,
   148→                _ => corrupted_count += 1,
   149→            }
   150→
   151→            reports.push(report);
   152→        }
   153→
   154→        let overall_health = if total_files > 0 {
   155→            valid_count as f64 / total_files as f64
   156→        } else {
   157→            1.0
   158→        };
   159→
   160→        let snapshot = ConsistencySnapshot {
   161→            timestamp: self.current_timestamp(),
   162→            total_files,
   163→            valid_files: valid_count,
   164→            corrupted_files: corrupted_count,
   165→            file_reports: reports,
   166→            overall_health,
   167→        };
   168→
   169→        self.snapshots.push(snapshot.clone());
   170→        snapshot
   171→    }
   172→
   173→    /// 스냅샷 이력 조회
   174→    pub fn get_snapshots(&self) -> &[ConsistencySnapshot] {
   175→        &self.snapshots
   176→    }
   177→
   178→    /// 최근 스냅샷
   179→    pub fn latest_snapshot(&self) -> Option<ConsistencySnapshot> {
   180→        self.snapshots.last().cloned()
   181→    }
   182→
   183→    /// 시스템 건강도 추이
   184→    pub fn health_trend(&self) -> Vec<(u64, f64)> {
   185→        self.snapshots
   186→            .iter()
   187→            .map(|s| (s.timestamp, s.overall_health))
   188→            .collect()
   189→    }
   190→
   191→    /// 무결성 통계
   192→    pub fn integrity_stats(&self) -> IntegrityStats {
   193→        let total_checks = self.total_checks;
   194→        let total_corruptions = self.total_corruptions_detected;
   195→
   196→        let corruption_rate = if total_checks > 0 {
   197→            total_corruptions as f64 / total_checks as f64
   198→        } else {
   199→            0.0
   200→        };
   201→
   202→        IntegrityStats {
   203→            total_checks,
   204→            corruptions_found: total_corruptions,
   205→            corruption_rate,
   206→            snapshots_taken: self.snapshots.len(),
   207→        }
   208→    }
   209→
   210→    #[inline]
   211→    fn current_timestamp(&self) -> u64 {
   212→        self.total_checks as u64
   213→    }
   214→}
   215→
   216→/// 무결성 통계
   217→#[derive(Clone, Debug)]
   218→pub struct IntegrityStats {
   219→    pub total_checks: usize,
   220→    pub corruptions_found: usize,
   221→    pub corruption_rate: f64,
   222→    pub snapshots_taken: usize,
   223→}
   224→
   225→#[cfg(test)]
   226→mod tests {
   227→    use super::*;
   228→
   229→    #[test]
   230→    fn test_integrity_checker_creation() {
   231→        let checker = IntegrityChecker::new();
   232→        assert_eq!(checker.total_checks, 0);
   233→    }
   234→
   235→    #[test]
   236→    fn test_integrity_status_enum() {
   237→        assert_eq!(IntegrityStatus::Valid, IntegrityStatus::Valid);
   238→        assert_ne!(IntegrityStatus::Valid, IntegrityStatus::Corrupted);
   239→    }
   240→
   241→    #[test]
   242→    fn test_verify_valid_file() {
   243→        let mut checker = IntegrityChecker::new();
   244→        let engine = HashEngine::new();
   245→        let data = b"Test data";
   246→
   247→        let mut store = ChunkStore::new();
   248→        store.store_chunked(data);
   249→
   250→        let manifest = FileManifest {
   251→            file_hash: engine.sha256(data),
   252→            chunk_hashes: vec![engine.sha256(data)],
   253→            file_size: data.len(),
   254→            stored_timestamp: 1,
   255→            immutable: true,
   256→        };
   257→
   258→        let report = checker.verify_file("test.txt", &manifest, &store);
   259→        assert_eq!(report.status, IntegrityStatus::Valid);
   260→    }
   261→
   262→    #[test]
   263→    fn test_integrity_report() {
   264→        let report = IntegrityReport {
   265→            filename: "test.txt".to_string(),
   266→            status: IntegrityStatus::Valid,
   267→            original_hash: "abc123".to_string(),
   268→            computed_hash: "abc123".to_string(),
   269→            checked_at: 1,
   270→            chunk_status: vec![],
   271→        };
   272→
   273→        assert_eq!(report.status, IntegrityStatus::Valid);
   274→    }
   275→
   276→    #[test]
   277→    fn test_snapshot_creation() {
   278→        let mut checker = IntegrityChecker::new();
   279→        let engine = HashEngine::new();
   280→        let data = b"Snapshot test";
   281→
   282→        let mut store = ChunkStore::new();
   283→        store.store_chunked(data);
   284→
   285→        let mut manifests = HashMap::new();
   286→        let manifest = FileManifest {
   287→            file_hash: engine.sha256(data),
   288→            chunk_hashes: vec![engine.sha256(data)],
   289→            file_size: data.len(),
   290→            stored_timestamp: 1,
   291→            immutable: true,
   292→        };
   293→        manifests.insert("test.txt".to_string(), manifest);
   294→
   295→        let snapshot = checker.create_snapshot(&manifests, &store);
   296→        assert!(snapshot.total_files > 0);
   297→    }
   298→
   299→    #[test]
   300→    fn test_health_trend() {
   301→        let mut checker = IntegrityChecker::new();
   302→        let engine = HashEngine::new();
   303→        let data = b"Trend test";
   304→
   305→        let mut store = ChunkStore::new();
   306→        store.store_chunked(data);
   307→
   308→        let mut manifests = HashMap::new();
   309→        let manifest = FileManifest {
   310→            file_hash: engine.sha256(data),
   311→            chunk_hashes: vec![engine.sha256(data)],
   312→            file_size: data.len(),
   313→            stored_timestamp: 1,
   314→            immutable: true,
   315→        };
   316→        manifests.insert("test.txt".to_string(), manifest);
   317→
   318→        checker.create_snapshot(&manifests, &store);
   319→        let trend = checker.health_trend();
   320→        assert!(!trend.is_empty());
   321→    }
   322→}
