     1→// Phase 3: Real-time Integrity Monitoring System
     2→// 백그라운드 검증 + 자동 복구
     3→
     4→use crate::cas::*;
     5→use crate::integrity::*;
     6→use std::collections::HashMap;
     7→
     8→/// 모니터링 이벤트
     9→#[derive(Clone, Debug, PartialEq)]
    10→pub enum MonitoringEvent {
    11→    FileAccessed(String),        // 파일 접근
    12→    FileModified(String),        // 파일 수정
    13→    CorruptionDetected(String),  // 손상 감지
    14→    RecoveryStarted(String),     // 복구 시작
    15→    RecoveryCompleted(String),   // 복구 완료
    16→    VerificationPassed(String),  // 검증 통과
    17→    VerificationFailed(String),  // 검증 실패
    18→}
    19→
    20→/// 복구 전략
    21→#[derive(Clone, Debug, PartialEq)]
    22→pub enum RecoveryStrategy {
    23→    Restore,      // 백업에서 복원
    24→    Reconstruct,  // 청크에서 재구성
    25→    Quarantine,   // 격리
    26→    Manual,       // 수동 개입
    27→}
    28→
    29→/// 복구 결과
    30→#[derive(Clone, Debug)]
    31→pub struct RecoveryResult {
    32→    pub filename: String,
    33→    pub strategy: RecoveryStrategy,
    34→    pub success: bool,
    35→    pub timestamp: u64,
    36→    pub error_message: Option<String>,
    37→}
    38→
    39→/// 실시간 모니터링 시스템
    40→pub struct RealtimeMonitor {
    41→    // 파일별 접근 카운트
    42→    access_counts: HashMap<String, usize>,
    43→    // 파일별 마지막 검증 시각
    44→    last_verifications: HashMap<String, u64>,
    45→    // 모니터링 이벤트 로그
    46→    event_log: Vec<(u64, MonitoringEvent)>,
    47→    // 복구 결과 이력
    48→    recovery_history: Vec<RecoveryResult>,
    49→    // 설정: 검증 간격 (접근 횟수)
    50→    verification_interval: usize,
    51→    // 설정: 자동 복구 활성화
    52→    auto_recovery_enabled: bool,
    53→    // 통계
    54→    total_accesses: usize,
    55→    total_corruptions_detected: usize,
    56→    total_recoveries: usize,
    57→    successful_recoveries: usize,
    58→}
    59→
    60→impl RealtimeMonitor {
    61→    pub fn new() -> Self {
    62→        RealtimeMonitor {
    63→            access_counts: HashMap::new(),
    64→            last_verifications: HashMap::new(),
    65→            event_log: Vec::new(),
    66→            recovery_history: Vec::new(),
    67→            verification_interval: 10,  // 10회 접근마다 검증
    68→            auto_recovery_enabled: true,
    69→            total_accesses: 0,
    70→            total_corruptions_detected: 0,
    71→            total_recoveries: 0,
    72→            successful_recoveries: 0,
    73→        }
    74→    }
    75→
    76→    /// 파일 접근 기록
    77→    pub fn record_access(&mut self, filename: &str) -> bool {
    78→        self.total_accesses += 1;
    79→        let count = self.access_counts.entry(filename.to_string()).or_insert(0);
    80→        *count += 1;
    81→
    82→        self.log_event(MonitoringEvent::FileAccessed(filename.to_string()));
    83→
    84→        // 검증 필요 여부 확인
    85→        *count >= self.verification_interval
    86→    }
    87→
    88→    /// 파일 검증 (접근 기반)
    89→    pub fn verify_on_access(&mut self, filename: &str, manifest: &FileManifest, store: &ChunkStore) -> IntegrityStatus {
    90→        let mut checker = IntegrityChecker::new();
    91→        let report = checker.verify_file(filename, manifest, store);
    92→
    93→        self.last_verifications.insert(filename.to_string(), self.current_timestamp());
    94→
    95→        match report.status {
    96→            IntegrityStatus::Valid => {
    97→                self.log_event(MonitoringEvent::VerificationPassed(filename.to_string()));
    98→                // 접근 카운트 리셋
    99→                self.access_counts.insert(filename.to_string(), 0);
   100→                IntegrityStatus::Valid
   101→            }
   102→            _ => {
   103→                self.total_corruptions_detected += 1;
   104→                self.log_event(MonitoringEvent::CorruptionDetected(filename.to_string()));
   105→                report.status
   106→            }
   107→        }
   108→    }
   109→
   110→    /// 자동 복구 시도
   111→    pub fn attempt_recovery(&mut self, filename: &str, manifest: &FileManifest, store: &ChunkStore) -> RecoveryResult {
   112→        self.total_recoveries += 1;
   113→
   114→        self.log_event(MonitoringEvent::RecoveryStarted(filename.to_string()));
   115→
   116→        // 복구 전략 선택: 청크에서 재구성
   117→        let strategy = RecoveryStrategy::Reconstruct;
   118→
   119→        // 재구성 시도
   120→        let mut reconstructed = Vec::new();
   121→        let mut all_chunks_available = true;
   122→
   123→        for chunk_hash in &manifest.chunk_hashes {
   124→            if let Some(chunk) = store.get_chunk(chunk_hash) {
   125→                reconstructed.extend_from_slice(&chunk);
   126→            } else {
   127→                all_chunks_available = false;
   128→                break;
   129→            }
   130→        }
   131→
   132→        reconstructed.truncate(manifest.file_size);
   133→
   134→        let engine = HashEngine::new();
   135→        let recalc_hash = engine.sha256(&reconstructed);
   136→
   137→        let success = all_chunks_available && (recalc_hash == manifest.file_hash);
   138→
   139→        if success {
   140→            self.successful_recoveries += 1;
   141→            self.log_event(MonitoringEvent::RecoveryCompleted(filename.to_string()));
   142→        }
   143→
   144→        let result = RecoveryResult {
   145→            filename: filename.to_string(),
   146→            strategy: strategy.clone(),
   147→            success,
   148→            timestamp: self.current_timestamp(),
   149→            error_message: if success {
   150→                None
   151→            } else {
   152→                Some("Failed to reconstruct file from chunks".to_string())
   153→            },
   154→        };
   155→
   156→        self.recovery_history.push(result.clone());
   157→        result
   158→    }
   159→
   160→    /// 정기적 배경 검증 (주기적 호출)
   161→    pub fn background_verification(&mut self, manifests: &HashMap<String, FileManifest>, store: &ChunkStore) -> Vec<IntegrityStatus> {
   162→        let mut results = Vec::new();
   163→
   164→        for (filename, manifest) in manifests {
   165→            // 오래된 검증 대상부터 확인
   166→            let last_check = self.last_verifications.get(filename).copied().unwrap_or(0);
   167→            if self.current_timestamp() - last_check > 100 {
   168→                let status = self.verify_on_access(filename, manifest, store);
   169→                results.push(status);
   170→            }
   171→        }
   172→
   173→        results
   174→    }
   175→
   176→    /// 모니터링 이벤트 로그
   177→    pub fn get_event_log(&self) -> &[(u64, MonitoringEvent)] {
   178→        &self.event_log
   179→    }
   180→
   181→    /// 복구 이력
   182→    pub fn get_recovery_history(&self) -> &[RecoveryResult] {
   183→        &self.recovery_history
   184→    }
   185→
   186→    /// 복구 성공률
   187→    pub fn recovery_success_rate(&self) -> f64 {
   188→        if self.total_recoveries == 0 {
   189→            0.0
   190→        } else {
   191→            self.successful_recoveries as f64 / self.total_recoveries as f64
   192→        }
   193→    }
   194→
   195→    /// 파일별 접근 패턴
   196→    pub fn access_patterns(&self) -> Vec<(String, usize)> {
   197→        let mut patterns: Vec<_> = self.access_counts
   198→            .iter()
   199→            .map(|(k, v)| (k.clone(), *v))
   200→            .collect();
   201→        patterns.sort_by(|a, b| b.1.cmp(&a.1));
   202→        patterns
   203→    }
   204→
   205→    /// 모니터링 통계
   206→    pub fn monitoring_stats(&self) -> MonitoringStats {
   207→        MonitoringStats {
   208→            total_accesses: self.total_accesses,
   209→            corruptions_detected: self.total_corruptions_detected,
   210→            total_recoveries: self.total_recoveries,
   211→            successful_recoveries: self.successful_recoveries,
   212→            recovery_success_rate: self.recovery_success_rate(),
   213→            corruption_rate: if self.total_accesses > 0 {
   214→                self.total_corruptions_detected as f64 / self.total_accesses as f64
   215→            } else {
   216→                0.0
   217→            },
   218→        }
   219→    }
   220→
   221→    // ===== Private Methods =====
   222→
   223→    fn log_event(&mut self, event: MonitoringEvent) {
   224→        let timestamp = self.current_timestamp();
   225→        self.event_log.push((timestamp, event));
   226→    }
   227→
   228→    #[inline]
   229→    fn current_timestamp(&self) -> u64 {
   230→        self.event_log.len() as u64
   231→    }
   232→}
