     1→// Phase 1: Content-Addressable Storage 핵심 엔진
     2→// 파일을 해시값으로 주소 지정하고 변조 불가능성 보장
     3→
     4→use crate::cas::hash_engine::{Hash256, HashEngine};
     5→use crate::cas::chunk_store::{ChunkStore, CHUNK_SIZE};
     6→use std::collections::HashMap;
     7→
     8→/// 파일 메니페스트 (파일의 청크 구조)
     9→#[derive(Clone, Debug)]
    10→pub struct FileManifest {
    11→    pub file_hash: Hash256,           // 파일 전체 해시
    12→    pub chunk_hashes: Vec<Hash256>,   // 청크 해시들
    13→    pub file_size: usize,
    14→    pub stored_timestamp: u64,
    15→    pub immutable: bool,              // 변조 불가능 플래그
    16→}
    17→
    18→impl FileManifest {
    19→    /// 무결성 검증: 현재 청크들의 해시가 매니페스트와 일치하는지 확인
    20→    pub fn verify_integrity(&self, store: &ChunkStore) -> bool {
    21→        let mut reconstructed = Vec::new();
    22→
    23→        for chunk_hash in &self.chunk_hashes {
    24→            if let Some(chunk) = store.get_chunk(chunk_hash) {
    25→                reconstructed.extend_from_slice(&chunk);
    26→            } else {
    27→                return false;  // 청크 누락
    28→            }
    29→        }
    30→
    31→        // 재구성된 파일의 해시 계산
    32→        let engine = HashEngine::new();
    33→        let recalc_hash = engine.sha256(&reconstructed);
    34→
    35→        // 원래 파일 해시와 비교
    36→        recalc_hash == self.file_hash
    37→    }
    38→}
    39→
    40→/// Content-Addressable Storage 코어
    41→pub struct CASCore {
    42→    store: ChunkStore,
    43→    engine: HashEngine,
    44→    // 파일명 → 매니페스트 (선택적, CAS의 주요 기능 아님)
    45→    manifests: HashMap<String, FileManifest>,
    46→    total_files: usize,
    47→}
    48→
    49→impl CASCore {
    50→    pub fn new() -> Self {
    51→        CASCore {
    52→            store: ChunkStore::new(),
    53→            engine: HashEngine::new(),
    54→            manifests: HashMap::new(),
    55→            total_files: 0,
    56→        }
    57→    }
    58→
    59→    /// 파일 저장 (CAS 방식)
    60→    /// 반환: (파일 해시, 매니페스트)
    61→    pub fn store_file(&mut self, filename: &str, data: &[u8]) -> (Hash256, FileManifest) {
    62→        // 파일 전체 해시 계산
    63→        let file_hash = self.engine.sha256(data);
    64→
    65→        // 청크로 분할하여 저장
    66→        self.store.store_chunked(data);
    67→
    68→        // 매니페스트 생성
    69→        let chunk_hashes = self.chunk_hashes(data);
    70→        let manifest = FileManifest {
    71→            file_hash: file_hash.clone(),
    72→            chunk_hashes,
    73→            file_size: data.len(),
    74→            stored_timestamp: self.current_timestamp(),
    75→            immutable: true,  // CAS의 핵심: 저장되는 순간 불변
    76→        };
    77→
    78→        self.manifests.insert(filename.to_string(), manifest.clone());
    79→        self.total_files += 1;
    80→
    81→        (file_hash, manifest)
    82→    }
    83→
    84→    /// 파일 복원 (해시로부터)
    85→    pub fn retrieve_file(&self, file_hash: &Hash256) -> Option<Vec<u8>> {
    86→        // 매니페스트 찾기
    87→        for (_, manifest) in &self.manifests {
    88→            if manifest.file_hash == *file_hash {
    89→                return Some(self.reconstruct_from_manifest(manifest));
    90→            }
    91→        }
    92→        None
    93→    }
    94→
    95→    /// 파일명으로 복원
    96→    pub fn retrieve_by_name(&self, filename: &str) -> Option<Vec<u8>> {
    97→        self.manifests
    98→            .get(filename)
    99→            .map(|m| self.reconstruct_from_manifest(m))
   100→    }
   101→
   102→    /// 무결성 검증
   103→    pub fn verify_file(&self, file_hash: &Hash256) -> bool {
   104→        for (_, manifest) in &self.manifests {
   105→            if manifest.file_hash == *file_hash {
   106→                return manifest.verify_integrity(&self.store);
   107→            }
   108→        }
   109→        false
   110→    }
   111→
   112→    /// 파일명으로 무결성 검증
   113→    pub fn verify_by_name(&self, filename: &str) -> bool {
   114→        if let Some(manifest) = self.manifests.get(filename) {
   115→            manifest.verify_integrity(&self.store)
   116→        } else {
   117→            false
   118→        }
   119→    }
   120→
   121→    /// 중복 제거율
   122→    pub fn deduplication_ratio(&self) -> f64 {
   123→        self.store.deduplication_rate()
   124→    }
   125→
   126→    /// 저장소 통계
   127→    pub fn storage_stats(&self) -> CASStats {
   128→        let store_stats = self.store.stats();
   129→        CASStats {
   130→            total_files: self.total_files,
   131→            unique_chunks: store_stats.chunk_count,
   132→            stored_bytes: store_stats.stored_bytes,
   133→            deduplicated_bytes: store_stats.deduplicated_bytes,
   134→            deduplication_rate: store_stats.deduplication_rate,
   135→            compression_ratio: if store_stats.total_possible > 0 {
   136→                store_stats.stored_bytes as f64 / store_stats.total_possible as f64
   137→            } else {
   138→                1.0
   139→            },
   140→        }
   141→    }
   142→
   143→    /// 변조 가능 여부 검사 (CAS의 핵심 특성)
   144→    pub fn is_immutable(&self, filename: &str) -> bool {
   145→        self.manifests
   146→            .get(filename)
   147→            .map(|m| m.immutable)
   148→            .unwrap_or(false)
   149→    }
   150→
   151→    /// 모든 파일 나열
   152→    pub fn list_files(&self) -> Vec<String> {
   153→        self.manifests.keys().cloned().collect()
   154→    }
   155→
   156→    /// 파일 메타데이터
   157→    pub fn file_info(&self, filename: &str) -> Option<FileInfo> {
   158→        self.manifests.get(filename).map(|m| FileInfo {
   159→            hash: m.file_hash.to_hex(),
   160→            size: m.file_size,
   161→            chunks: m.chunk_hashes.len(),
   162→            immutable: m.immutable,
   163→            timestamp: m.stored_timestamp,
   164→        })
   165→    }
   166→
   167→    // ===== Private Methods =====
   168→
   169→    /// 파일의 청크 해시들 계산
   170→    fn chunk_hashes(&self, data: &[u8]) -> Vec<Hash256> {
   171→        let mut hashes = Vec::new();
   172→
   173→        for chunk_idx in 0..(data.len() + CHUNK_SIZE - 1) / CHUNK_SIZE {
   174→            let start = chunk_idx * CHUNK_SIZE;
   175→            let end = std::cmp::min(start + CHUNK_SIZE, data.len());
   176→            let chunk = &data[start..end];
   177→
   178→            let hash = self.engine.sha256(chunk);
   179→            hashes.push(hash);
   180→        }
   181→
   182→        hashes
   183→    }
   184→
   185→    /// 매니페스트로부터 파일 재구성
   186→    fn reconstruct_from_manifest(&self, manifest: &FileManifest) -> Vec<u8> {
   187→        let mut result = Vec::new();
   188→
   189→        for chunk_hash in &manifest.chunk_hashes {
   190→            if let Some(chunk) = self.store.get_chunk(chunk_hash) {
   191→                result.extend_from_slice(&chunk);
   192→            }
   193→        }
   194→
   195→        // 파일 크기로 트림
   196→        result.truncate(manifest.file_size);
   197→        result
   198→    }
   199→
   200→    #[inline]
   201→    fn current_timestamp(&self) -> u64 {
   202→        self.total_files as u64
   203→    }
   204→}
   205→
