   207→#[derive(Clone, Debug)]
   208→pub struct CASStats {
   209→    pub total_files: usize,
   210→    pub unique_chunks: usize,
   211→    pub stored_bytes: usize,
   212→    pub deduplicated_bytes: usize,
   213→    pub deduplication_rate: f64,
   214→    pub compression_ratio: f64,
   215→}
   216→
   217→/// 파일 정보
   218→#[derive(Clone, Debug)]
   219→pub struct FileInfo {
