     1→// Phase 1: 청크 저장소 (Chunk-based Content Storage)
     2→// 파일을 4KB 청크로 분할하여 저장
     3→// 목표: 중복 청크 감지 및 제거 기초 제공
     4→
     5→use crate::cas::hash_engine::{Hash256, HashEngine};
     6→use std::collections::HashMap;
     7→
     8→pub const CHUNK_SIZE: usize = 4096;  // 4KB 청크
     9→
    10→/// 저장된 청크 메타데이터
    11→#[derive(Clone, Debug)]
    12→pub struct ChunkMetadata {
    13→    pub hash: Hash256,
    14→    pub size: usize,
    15→    pub ref_count: usize,  // 이 청크를 참조하는 파일 수
    16→    pub stored_at: usize,  // 저장소 오프셋 (선택)
    17→    pub created_ts: u64,   // 생성 시간
    18→}
    19→
    20→/// 청크 저장소 (CAS 백엔드)
    21→pub struct ChunkStore {
    22→    engine: HashEngine,
    23→    // 해시 → 청크 메타데이터
    24→    chunks: HashMap<String, ChunkMetadata>,
    25→    // 실제 청크 데이터 (시뮬레이션)
    26→    data: HashMap<String, Vec<u8>>,
    27→    total_stored: usize,
    28→    total_deduplicated: usize,  // 제거된 중복 바이트 수
    29→}
    30→
    31→impl ChunkStore {
    32→    pub fn new() -> Self {
    33→        ChunkStore {
    34→            engine: HashEngine::new(),
    35→            chunks: HashMap::new(),
    36→            data: HashMap::new(),
    37→            total_stored: 0,
    38→            total_deduplicated: 0,
    39→        }
    40→    }
    41→
    42→    /// 데이터를 청크로 분할하고 저장
    43→    /// 반환: (저장된 청크 수, 중복 바이트 수)
    44→    pub fn store_chunked(&mut self, data: &[u8]) -> (usize, usize) {
    45→        let mut stored_count = 0;
    46→        let mut dedup_bytes = 0;
    47→
    48→        // 데이터를 청크로 분할
    49→        for chunk_idx in 0..(data.len() + CHUNK_SIZE - 1) / CHUNK_SIZE {
    50→            let start = chunk_idx * CHUNK_SIZE;
    51→            let end = std::cmp::min(start + CHUNK_SIZE, data.len());
    52→            let chunk = &data[start..end];
    53→
    54→            // 청크 해시 계산
    55→            let hash = self.engine.sha256(chunk);
    56→            let hash_hex = hash.to_hex();
    57→
    58→            // 중복 확인
    59→            if let Some(metadata) = self.chunks.get_mut(&hash_hex) {
    60→                // 중복: 참조 카운트만 증가
    61→                metadata.ref_count += 1;
    62→                dedup_bytes += chunk.len();
    63→            } else {
    64→                // 새 청크: 저장
    65→                let metadata = ChunkMetadata {
    66→                    hash: hash.clone(),
    67→                    size: chunk.len(),
    68→                    ref_count: 1,
    69→                    stored_at: self.total_stored,
    70→                    created_ts: self.current_timestamp(),
    71→                };
    72→                self.chunks.insert(hash_hex.clone(), metadata);
    73→                self.data.insert(hash_hex, chunk.to_vec());
    74→                self.total_stored += chunk.len();
    75→                stored_count += 1;
    76→            }
    77→        }
    78→
    79→        self.total_deduplicated += dedup_bytes;
    80→        (stored_count, dedup_bytes)
    81→    }
    82→
    83→    /// 청크 조회
    84→    pub fn get_chunk(&self, hash: &Hash256) -> Option<Vec<u8>> {
    85→        let hash_hex = hash.to_hex();
    86→        self.data.get(&hash_hex).cloned()
    87→    }
    88→
    89→    /// 해시로 청크 조회
    90→    pub fn get_chunk_by_hex(&self, hex: &str) -> Option<Vec<u8>> {
    91→        self.data.get(hex).cloned()
    92→    }
    93→
    94→    /// 청크 메타데이터 조회
    95→    pub fn get_metadata(&self, hash: &Hash256) -> Option<ChunkMetadata> {
    96→        let hash_hex = hash.to_hex();
    97→        self.chunks.get(&hash_hex).cloned()
    98→    }
    99→
   100→    /// 총 고유 청크 수
   101→    pub fn chunk_count(&self) -> usize {
   102→        self.chunks.len()
   103→    }
   104→
   105→    /// 저장된 바이트 수
   106→    pub fn stored_bytes(&self) -> usize {
   107→        self.total_stored
   108→    }
   109→
   110→    /// 중복으로 인해 절감된 바이트 수
   111→    pub fn deduplicated_bytes(&self) -> usize {
   112→        self.total_deduplicated
   113→    }
   114→
   115→    /// 총 저장 가능 바이트 (중복 포함)
   116→    pub fn total_possible_bytes(&self) -> usize {
   117→        self.total_stored + self.total_deduplicated
   118→    }
   119→
   120→    /// 중복 제거율 (%)
   121→    pub fn deduplication_rate(&self) -> f64 {
   122→        let total = self.total_possible_bytes();
   123→        if total == 0 {
   124→            0.0
   125→        } else {
   126→            (self.total_deduplicated as f64 / total as f64) * 100.0
   127→        }
   128→    }
   129→
   130→    /// 특정 청크의 참조 수
   131→    pub fn ref_count(&self, hash: &Hash256) -> usize {
   132→        let hash_hex = hash.to_hex();
   133→        self.chunks
   134→            .get(&hash_hex)
   135→            .map(|m| m.ref_count)
   136→            .unwrap_or(0)
   137→    }
   138→
   139→    /// 청크 참조 해제 (삭제 시)
   140→    pub fn dereference_chunk(&mut self, hash: &Hash256) -> bool {
   141→        let hash_hex = hash.to_hex();
   142→        if let Some(metadata) = self.chunks.get_mut(&hash_hex) {
   143→            if metadata.ref_count > 1 {
   144→                metadata.ref_count -= 1;
   145→                false  // 청크는 아직 사용 중
   146→            } else {
   147→                true   // 청크 삭제 가능
   148→            }
   149→        } else {
   150→            false
   151→        }
   152→    }
   153→
   154→    /// 참조 카운트가 0이 된 청크 제거
   155→    pub fn garbage_collect(&mut self) -> usize {
   156→        let mut removed = 0;
   157→        let to_remove: Vec<String> = self
   158→            .chunks
   159→            .iter()
   160→            .filter(|(_, m)| m.ref_count == 0)
   161→            .map(|(k, _)| k.clone())
   162→            .collect();
   163→
   164→        for hash_hex in to_remove {
   165→            if let Some(metadata) = self.chunks.remove(&hash_hex) {
   166→                self.total_stored -= metadata.size;
   167→                self.data.remove(&hash_hex);
   168→                removed += 1;
   169→            }
   170→        }
   171→        removed
   172→    }
   173→
   174→    /// 저장소 통계
   175→    pub fn stats(&self) -> StorageStats {
   176→        StorageStats {
   177→            chunk_count: self.chunk_count(),
   178→            stored_bytes: self.total_stored,
   179→            deduplicated_bytes: self.total_deduplicated,
   180→            deduplication_rate: self.deduplication_rate(),
   181→            total_possible: self.total_possible_bytes(),
   182→        }
   183→    }
   184→
   185→    #[inline]
   186→    fn current_timestamp(&self) -> u64 {
   187→        // 시뮬레이션: 간단한 카운터
   188→        self.chunks.len() as u64
   189→    }
   190→}
   191→
   192→/// 저장소 통계
   193→#[derive(Clone, Debug)]
   194→pub struct StorageStats {
   195→    pub chunk_count: usize,
   196→    pub stored_bytes: usize,
   197→    pub deduplicated_bytes: usize,
   198→    pub deduplication_rate: f64,
   199→    pub total_possible: usize,
   200→}
