     4→use std::collections::HashMap;
     5→
     6→/// SHA256 해시 출력 (64 hex chars = 256 bits)
     7→#[derive(Clone, PartialEq, Eq, Hash, Debug)]
     8→pub struct Hash256 {
     9→    pub bytes: [u8; 32],  // 256 bits = 32 bytes
    10→}
    11→
    12→impl Hash256 {
    13→    /// 16진수 문자열로 표현
    14→    pub fn to_hex(&self) -> String {
    15→        let mut result = String::new();
    16→        for byte in self.bytes.iter() {
    17→            result.push_str(&format!("{:02x}", byte));
    18→        }
    19→        result
    20→    }
    21→
    22→    /// 16진수 문자열에서 파싱
    23→    pub fn from_hex(hex: &str) -> Option<Self> {
    24→        if hex.len() != 64 {
    25→            return None;
    26→        }
    27→        let mut bytes = [0u8; 32];
    28→        for i in 0..32 {
    29→            let byte_str = &hex[i * 2..i * 2 + 2];
    30→            bytes[i] = u8::from_str_radix(byte_str, 16).ok()?;
    31→        }
    32→        Some(Hash256 { bytes })
    33→    }
    34→}
    35→
    36→/// SHA256 해시 엔진
    37→/// 실제 환경에서는 OpenSSL/BoringSSL 사용
    38→/// 여기서는 알고리즘 검증 목적의 시뮬레이션
    39→pub struct HashEngine {
    40→    // SHA256 상수 (64개)
    41→    k: [u32; 64],
    42→}
    43→
    44→impl HashEngine {
    45→    pub fn new() -> Self {
    46→        // SHA256 초기화 상수 (처음 64개 소수의 세제곱근의 소수 부분)
    47→        let k = [
    48→            0x428a2f98, 0x71374491, 0xb5c0fbcf, 0xe9b5dba5, 0x3956c25b, 0x59f111f1, 0x923f82a4, 0xab1c5ed5,
    49→            0xd807aa98, 0x12835b01, 0x243185be, 0x550c7dc3, 0x72be5d74, 0x80deb1fe, 0x9bdc06a7, 0xc19bf174,
    50→            0xe49b69c1, 0xefbe4786, 0x0fc19dc6, 0x240ca1cc, 0x2de92c6f, 0x4a7484aa, 0x5cb0a9dc, 0x76f988da,
    51→            0x983e5152, 0xa831c66d, 0xb00327c8, 0xbf597fc7, 0xc6e00bf3, 0xd5a79147, 0x06ca6351, 0x14292967,
    52→            0x27b70a85, 0x2e1b2138, 0x4d2c6dfc, 0x53380d13, 0x650a7354, 0x766a0abb, 0x81c2c92e, 0x92722c85,
    53→            0xa2bfe8a1, 0xa81a664b, 0xc24b8b70, 0xc76c51a3, 0xd192e819, 0xd6990624, 0xf40e3585, 0x106aa070,
    54→            0x19a4c116, 0x1e376c08, 0x2748774c, 0x34b0bcb5, 0x391c0cb3, 0x4ed8aa4a, 0x5b9cca4f, 0x682e6ff3,
    55→            0x748f82ee, 0x78a5636f, 0x84c87814, 0x8cc70208, 0x90befffa, 0xa4506ceb, 0xbef9a3f7, 0xc67178f2,
    56→        ];
    57→        HashEngine { k }
    58→    }
    59→
    60→    /// SHA256 계산 (검증 목적의 간단한 구현)
    61→    /// 실제 환경에서는 표준 구현 사용
    62→    pub fn sha256(&self, data: &[u8]) -> Hash256 {
    63→        // 초기 해시 값 (처음 8개 소수의 제곱근의 소수 부분)
    64→        let mut h = [
    65→            0x6a09e667u32,
    66→            0xbb67ae85u32,
    67→            0x3c6ef372u32,
    68→            0xa54ff53au32,
    69→            0x510e527fu32,
    70→            0x9b05688cu32,
    71→            0x1f83d9abu32,
    72→            0x5be0cd19u32,
    73→        ];
    74→
    75→        // Pre-processing: 메시지 패딩
    76→        let mut msg = data.to_vec();
    77→        let original_len = msg.len() as u64;
    78→        msg.push(0x80);
    79→
    80→        while (msg.len() % 64) != 56 {
    81→            msg.push(0x00);
    82→        }
    83→
    84→        // 길이 추가 (비트 단위, big-endian)
    85→        let len_bits = original_len * 8;
    86→        for i in (0..8).rev() {
    87→            msg.push(((len_bits >> (i * 8)) & 0xff) as u8);
    88→        }
    89→
    90→        // 메인 루프: 512-bit 청크 처리
    91→        for chunk_idx in 0..(msg.len() / 64) {
    92→            let chunk_start = chunk_idx * 64;
    93→            let mut w = [0u32; 64];
    94→
    95→            // 첫 16개 단어: 청크에서 직접 복사
    96→            for i in 0..16 {
    97→                let offset = chunk_start + i * 4;
    98→                w[i] = ((msg[offset] as u32) << 24)
    99→                    | ((msg[offset + 1] as u32) << 16)
   100→                    | ((msg[offset + 2] as u32) << 8)
   101→                    | (msg[offset + 3] as u32);
   102→            }
   103→
   104→            // 16부터 63까지: 확장
   105→            for i in 16..64 {
   106→                let s0 = self.rightrotate(w[i - 15], 7) ^ self.rightrotate(w[i - 15], 18) ^ (w[i - 15] >> 3);
   107→                let s1 = self.rightrotate(w[i - 2], 17) ^ self.rightrotate(w[i - 2], 19) ^ (w[i - 2] >> 10);
   108→                w[i] = w[i - 16].wrapping_add(s0).wrapping_add(w[i - 7]).wrapping_add(s1);
   109→            }
   110→
   111→            // 압축
   112→            let mut a = h[0];
   113→            let mut b = h[1];
   114→            let mut c = h[2];
   115→            let mut d = h[3];
   116→            let mut e = h[4];
   117→            let mut f = h[5];
   118→            let mut g = h[6];
   119→            let mut hs = h[7];
   120→
   121→            for i in 0..64 {
   122→                let s1 = self.rightrotate(e, 6) ^ self.rightrotate(e, 11) ^ self.rightrotate(e, 25);
   123→                let ch = (e & f) ^ ((!e) & g);
   124→                let temp1 = hs.wrapping_add(s1).wrapping_add(ch).wrapping_add(self.k[i]).wrapping_add(w[i]);
   125→                let s0 = self.rightrotate(a, 2) ^ self.rightrotate(a, 13) ^ self.rightrotate(a, 22);
   126→                let maj = (a & b) ^ (a & c) ^ (b & c);
   127→                let temp2 = s0.wrapping_add(maj);
   128→
   129→                hs = g;
   130→                g = f;
   131→                f = e;
   132→                e = d.wrapping_add(temp1);
   133→                d = c;
   134→                c = b;
   135→                b = a;
   136→                a = temp1.wrapping_add(temp2);
   137→            }
   138→
   139→            h[0] = h[0].wrapping_add(a);
   140→            h[1] = h[1].wrapping_add(b);
   141→            h[2] = h[2].wrapping_add(c);
   142→            h[3] = h[3].wrapping_add(d);
   143→            h[4] = h[4].wrapping_add(e);
   144→            h[5] = h[5].wrapping_add(f);
   145→            h[6] = h[6].wrapping_add(g);
   146→            h[7] = h[7].wrapping_add(hs);
   147→        }
   148→
   149→        // 최종 해시 값 생성 (big-endian)
   150→        let mut result = [0u8; 32];
   151→        for i in 0..8 {
   152→            result[i * 4] = ((h[i] >> 24) & 0xff) as u8;
   153→            result[i * 4 + 1] = ((h[i] >> 16) & 0xff) as u8;
   154→            result[i * 4 + 2] = ((h[i] >> 8) & 0xff) as u8;
   155→            result[i * 4 + 3] = (h[i] & 0xff) as u8;
   156→        }
   157→
   158→        Hash256 { bytes: result }
   159→    }
   160→
   161→    #[inline]
   162→    fn rightrotate(&self, x: u32, n: u32) -> u32 {
   163→        (x >> n) | (x << (32 - n))
   164→    }
   165→}
