     1→// Phase 2: Advanced Deduplication Engine
     2→// 고급 중복 제거: 정확한 중복 + 유사한 콘텐츠 감지
     3→
     4→use crate::cas::*;
     5→use std::collections::HashMap;
     6→
     7→/// 유사도 점수 (0.0 ~ 1.0)
     8→/// 1.0 = 정확히 동일
     9→/// 0.9+ = 매우 유사 (99%+ 일치)
    10→/// 0.7+ = 유사 (70%+ 일치)
    11→#[derive(Clone, Copy, Debug, PartialEq)]
    12→pub struct SimilarityScore(f64);
    13→
    14→impl SimilarityScore {
    15→    pub fn new(score: f64) -> Self {
    16→        SimilarityScore(score.max(0.0).min(1.0))
    17→    }
    18→
    19→    pub fn value(&self) -> f64 {
    20→        self.0
    21→    }
    22→
    23→    pub fn is_identical(&self) -> bool {
    24→        (self.0 - 1.0).abs() < 0.0001
    25→    }
    26→
    27→    pub fn is_very_similar(&self) -> bool {
    28→        self.0 >= 0.99
    29→    }
    30→
    31→    pub fn is_similar(&self) -> bool {
    32→        self.0 >= 0.70
    33→    }
    34→}
    35→
    36→/// 유사한 파일 후보
    37→#[derive(Clone, Debug)]
    38→pub struct SimilarContent {
    39→    pub file_hash: String,      // 파일명
    40→    pub similarity: SimilarityScore,
    41→    pub shared_chunks: usize,   // 공유 청크 수
    42→    pub total_chunks: usize,    // 전체 청크 수
    43→    pub potential_savings: usize, // 절감 가능 바이트
    44→}
    45→
    46→/// 고급 중복 제거 엔진
    47→pub struct DedupEngine {
    48→    // 파일명 → 매니페스트
    49→    manifests: HashMap<String, FileManifest>,
    50→    // 청크 해시 → 파일 리스트
    51→    chunk_to_files: HashMap<String, Vec<String>>,
    52→    // 통계
    53→    total_dedup_found: usize,
    54→    total_savings: usize,
    55→}
    56→
    57→impl DedupEngine {
    58→    pub fn new() -> Self {
    59→        DedupEngine {
    60→            manifests: HashMap::new(),
    61→            chunk_to_files: HashMap::new(),
    62→            total_dedup_found: 0,
    63→            total_savings: 0,
    64→        }
    65→    }
    66→
    67→    /// 파일 등록 (매니페스트 기반)
    68→    pub fn register_file(&mut self, filename: &str, manifest: FileManifest) {
    69→        self.manifests.insert(filename.to_string(), manifest.clone());
    70→
    71→        // 청크 역 인덱스 생성
    72→        for chunk_hash in &manifest.chunk_hashes {
    73→            let hash_hex = chunk_hash.to_hex();
    74→            self.chunk_to_files
    75→                .entry(hash_hex)
    76→                .or_insert_with(Vec::new)
    77→                .push(filename.to_string());
    78→        }
    79→    }
    80→
    81→    /// 정확한 중복 파일 찾기
    82→    pub fn find_exact_duplicates(&self, filename: &str) -> Vec<String> {
    83→        if let Some(manifest) = self.manifests.get(filename) {
    84→            let mut duplicates = Vec::new();
    85→
    86→            // 이 파일의 청크들을 공유하는 다른 파일들 찾기
    87→            for chunk_hash in &manifest.chunk_hashes {
    88→                let hash_hex = chunk_hash.to_hex();
    89→                if let Some(files_using_chunk) = self.chunk_to_files.get(&hash_hex) {
    90→                    duplicates.extend(files_using_chunk.clone());
    91→                }
    92→            }
    93→
    94→            // 자기 자신 제거 및 정렬
    95→            duplicates.sort();
    96→            duplicates.dedup();
    97→            duplicates.retain(|f| f != filename);
    98→            duplicates
    99→        } else {
   100→            Vec::new()
   101→        }
   102→    }
   103→
   104→    /// 유사한 파일 찾기 (Content-based Similarity)
   105→    pub fn find_similar_files(&self, filename: &str, threshold: f64) -> Vec<SimilarContent> {
   106→        if let Some(target_manifest) = self.manifests.get(filename) {
   107→            let mut similar_files = Vec::new();
   108→
   109→            for (other_name, other_manifest) in &self.manifests {
   110→                if other_name == filename {
   111→                    continue;
   112→                }
   113→
   114→                // 유사도 계산: 공유 청크 비율
   115→                let (shared_count, similarity) = self.calculate_similarity(
   116→                    target_manifest,
   117→                    other_manifest,
   118→                );
   119→
   120→                if similarity.value() >= threshold {
   121→                    let potential_savings = self.calculate_savings(
   122→                        target_manifest,
   123→                        other_manifest,
   124→                        shared_count,
   125→                    );
   126→
   127→                    similar_files.push(SimilarContent {
   128→                        file_hash: other_name.clone(),
   129→                        similarity,
   130→                        shared_chunks: shared_count,
   131→                        total_chunks: other_manifest.chunk_hashes.len(),
   132→                        potential_savings,
   133→                    });
   134→                }
   135→            }
   136→
   137→            // 유사도 높은 순서로 정렬
   138→            similar_files.sort_by(|a, b| {
   139→                b.similarity.value()
   140→                    .partial_cmp(&a.similarity.value())
   141→                    .unwrap_or(std::cmp::Ordering::Equal)
   142→            });
   143→
   144→            similar_files
   145→        } else {
   146→            Vec::new()
   147→        }
   148→    }
   149→
   150→    /// 중복 제거 전략: 어느 파일을 유지할지 결정
   151→    pub fn dedup_strategy(&self, filename: &str) -> DedupStrategy {
   152→        let duplicates = self.find_exact_duplicates(filename);
   153→        let similar = self.find_similar_files(filename, 0.70);
   154→
   155→        let total_potential = duplicates.len() + similar.len();
   156→        let total_savings: usize = similar.iter().map(|s| s.potential_savings).sum();
   157→
   158→        DedupStrategy {
   159→            target_file: filename.to_string(),
   160→            exact_duplicates: duplicates.len(),
   161→            similar_files: similar.len(),
   162→            total_potential_savings: total_savings,
   163→            recommendation: if total_potential > 0 {
   164→                DedupRecommendation::Consolidate
   165→            } else {
   166→                DedupRecommendation::Keep
   167→            },
   168→        }
   169→    }
   170→
   171→    /// 모든 파일의 중복 통계
   172→    pub fn dedup_statistics(&self) -> DedupStats {
   173→        let mut exact_dup_groups = 0;
   174→        let mut similar_groups = 0;
   175→        let mut total_duplicated_files = 0;
   176→
   177→        let mut checked = std::collections::HashSet::new();
   178→
   179→        for filename in self.manifests.keys() {
   180→            if checked.contains(filename) {
   181→                continue;
   182→            }
   183→
   184→            let exact_dups = self.find_exact_duplicates(filename);
   185→            if !exact_dups.is_empty() {
   186→                exact_dup_groups += 1;
   187→                total_duplicated_files += 1 + exact_dups.len();
   188→                for dup in &exact_dups {
   189→                    checked.insert(dup.clone());
   190→                }
   191→            }
   192→
   193→            let similar = self.find_similar_files(filename, 0.70);
   194→            if !similar.is_empty() {
   195→                similar_groups += 1;
   196→            }
   197→
   198→            checked.insert(filename.clone());
   199→        }
   200→
   201→        DedupStats {
   202→            total_files: self.manifests.len(),
   203→            exact_duplicate_groups: exact_dup_groups,
   204→            similar_groups,
   205→            files_with_duplicates: total_duplicated_files,
   206→            dedup_percentage: if self.manifests.len() > 0 {
   207→                (total_duplicated_files as f64 / self.manifests.len() as f64) * 100.0
   208→            } else {
   209→                0.0
   210→            },
   211→        }
   212→    }
   213→
   214→    // ===== Private Methods =====
   215→
   216→    fn calculate_similarity(
   217→        &self,
   218→        manifest1: &FileManifest,
   219→        manifest2: &FileManifest,
   220→    ) -> (usize, SimilarityScore) {
   221→        let hashes1: std::collections::HashSet<_> = manifest1
   222→            .chunk_hashes
   223→            .iter()
   224→            .map(|h| h.to_hex())
   225→            .collect();
   226→        let hashes2: std::collections::HashSet<_> = manifest2
   227→            .chunk_hashes
   228→            .iter()
   229→            .map(|h| h.to_hex())
   230→            .collect();
   231→
   232→        let shared = hashes1.intersection(&hashes2).count();
   233→        let total = hashes1.union(&hashes2).count();
   234→
   235→        let similarity = if total > 0 {
   236→            shared as f64 / total as f64
   237→        } else {
   238→            0.0
   239→        };
   240→
   241→        (shared, SimilarityScore::new(similarity))
   242→    }
   243→
   244→    fn calculate_savings(
   245→        &self,
   246→        _manifest1: &FileManifest,
   247→        manifest2: &FileManifest,
   248→        shared_chunks: usize,
   249→    ) -> usize {
   250→        // 각 청크는 약 4KB
   251→        shared_chunks * 4096
   252→    }
   253→}
   254→
   255→/// 중복 제거 전략
   256→#[derive(Clone, Debug)]
   257→pub struct DedupStrategy {
   258→    pub target_file: String,
   259→    pub exact_duplicates: usize,
   260→    pub similar_files: usize,
   261→    pub total_potential_savings: usize,
   262→    pub recommendation: DedupRecommendation,
   263→}
   264→
   265→/// 중복 제거 권장사항
   266→#[derive(Clone, Debug, PartialEq)]
   267→pub enum DedupRecommendation {
   268→    Keep,           // 현재 상태 유지
   269→    Consolidate,    // 중복 파일 통합
   270→    Archive,        // 아카이브로 이동
   271→}
   272→
   273→/// 중복 제거 통계
   274→#[derive(Clone, Debug)]
   275→pub struct DedupStats {
   276→    pub total_files: usize,
   277→    pub exact_duplicate_groups: usize,
   278→    pub similar_groups: usize,
   279→    pub files_with_duplicates: usize,
   280→    pub dedup_percentage: f64,
   281→}
