     1→// Phase 5: DMA Cache Manager
     2→// DMA 인식 캐싱 + 프리페치 버퍼 관리
     3→
     4→use crate::predictor::*;
     5→use std::collections::HashMap;
     6→
     7→/// DMA 전송 크기 클래스
     8→#[derive(Clone, Debug, PartialEq)]
     9→pub enum DMASize {
    10→    Small,    // 1-4KB
    11→    Medium,   // 4-64KB
    12→    Large,    // 64KB-1MB
    13→    Huge,     // >1MB
    14→}
    15→
    16→impl DMASize {
    17→    pub fn from_bytes(size: usize) -> Self {
    18→        match size {
    19→            0..=4096 => DMASize::Small,
    20→            4097..=65536 => DMASize::Medium,
    21→            65537..=1048576 => DMASize::Large,
    22→            _ => DMASize::Huge,
    23→        }
    24→    }
    25→
    26→    pub fn priority(&self) -> usize {
    27→        match self {
    28→            DMASize::Small => 3,
    29→            DMASize::Medium => 2,
    30→            DMASize::Large => 1,
    31→            DMASize::Huge => 0,  // 최우선 (인터럽트 최소)
    32→        }
    33→    }
    34→
    35→    pub fn dma_efficiency(&self) -> f64 {
    36→        match self {
    37→            DMASize::Small => 0.6,    // 오버헤드 40%
    38→            DMASize::Medium => 0.85,  // 오버헤드 15%
    39→            DMASize::Large => 0.95,   // 오버헤드 5%
    40→            DMASize::Huge => 0.99,    // 오버헤드 1%
    41→        }
    42→    }
    43→}
    44→
    45→/// 캐시 라인
    46→#[derive(Clone, Debug)]
    47→pub struct CacheLine {
    48→    pub filename: String,
    49→    pub offset: usize,
    50→    pub size: usize,
    51→    pub dma_size: DMASize,
    52→    pub data: Vec<u8>,
    53→    pub access_count: usize,
    54→    pub last_access: u64,
    55→    pub is_prefetched: bool,
    56→}
    57→
    58→impl CacheLine {
    59→    pub fn new(filename: String, offset: usize, size: usize, data: Vec<u8>, is_prefetched: bool) -> Self {
    60→        CacheLine {
    61→            filename,
    62→            offset,
    63→            size,
    64→            dma_size: DMASize::from_bytes(size),
    65→            data,
    66→            access_count: 0,
    67→            last_access: 0,
    68→            is_prefetched,
    69→        }
    70→    }
    71→
    72→    pub fn access(&mut self, timestamp: u64) {
    73→        self.access_count += 1;
    74→        self.last_access = timestamp;
    75→    }
    76→
    77→    pub fn dma_efficiency(&self) -> f64 {
    78→        self.dma_size.dma_efficiency()
    79→    }
    80→}
