    82→/// 캐시 우선순위
    83→#[derive(Clone, Debug, PartialEq, Eq, PartialOrd, Ord)]
    84→pub enum CachePriority {
    85→    Low,
    86→    Medium,
    87→    High,
    88→    Critical,
    89→}
    90→
    91→impl CachePriority {
    92→    pub fn from_score(score: f64, access_count: usize) -> Self {
    93→        let weighted_score = score * 0.7 + (access_count as f64 / 10.0).min(1.0) * 0.3;
    94→
    95→        if weighted_score >= 0.8 {
    96→            CachePriority::Critical
    97→        } else if weighted_score >= 0.6 {
    98→            CachePriority::High
    99→        } else if weighted_score >= 0.4 {
   100→            CachePriority::Medium
   101→        } else {
   102→            CachePriority::Low
   103→        }
   104→    }
   105→
   106→    pub fn eviction_priority(&self) -> usize {
   107→        match self {
   108→            CachePriority::Low => 0,
   109→            CachePriority::Medium => 1,
   110→            CachePriority::High => 2,
   111→            CachePriority::Critical => 3,
   112→        }
   113→    }
   114→}
   115→
   116→/// DMA 캐시 관리자
   117→#[derive(Clone, Debug)]
   118→pub struct DMACache {
   119→    pub cache_lines: HashMap<String, Vec<CacheLine>>,
   120→    pub max_size: usize,
   121→    pub current_size: usize,
   122→    pub prefetch_buffer_size: usize,
   123→    pub prefetch_buffer_used: usize,
   124→    pub hit_count: usize,
   125→    pub miss_count: usize,
   126→    pub eviction_count: usize,
   127→    pub dma_transfers: usize,
   128→}
   129→
   130→impl DMACache {
   131→    pub fn new(max_size: usize, prefetch_buffer_size: usize) -> Self {
   132→        DMACache {
   133→            cache_lines: HashMap::new(),
   134→            max_size,
   135→            current_size: 0,
   136→            prefetch_buffer_size,
   137→            prefetch_buffer_used: 0,
   138→            hit_count: 0,
   139→            miss_count: 0,
   140→            eviction_count: 0,
   141→            dma_transfers: 0,
   142→        }
   143→    }
   144→
   145→    /// 캐시 조회
   146→    pub fn lookup(&mut self, filename: &str, offset: usize, size: usize, timestamp: u64) -> Option<Vec<u8>> {
   147→        if let Some(lines) = self.cache_lines.get_mut(filename) {
   148→            for line in lines {
   149→                if line.offset <= offset && offset + size <= line.offset + line.size {
   150→                    line.access(timestamp);
   151→                    self.hit_count += 1;
   152→                    return Some(line.data.clone());
   153→                }
   154→            }
   155→        }
   156→        self.miss_count += 1;
   157→        None
   158→    }
   159→
   160→    /// 프리페치를 통한 캐시 추가
   161→    pub fn add_prefetch_line(&mut self, line: CacheLine) -> bool {
   162→        if self.prefetch_buffer_used + line.size > self.prefetch_buffer_size {
   163→            return false;  // 프리페치 버퍼 부족
   164→        }
   165→
   166→        self.prefetch_buffer_used += line.size;
   167→        self.current_size += line.size;
   168→
   169→        self.cache_lines
   170→            .entry(line.filename.clone())
   171→            .or_insert_with(Vec::new)
   172→            .push(line);
   173→
   174→        self.dma_transfers += 1;
   175→        true
   176→    }
   177→
   178→    /// 일반 캐시 추가 (접근 기반)
   179→    pub fn add_cache_line(&mut self, line: CacheLine) -> bool {
   180→        if self.current_size + line.size > self.max_size {
   181→            // 캐시 부족 → eviction
   182→            if !self.evict_one() {
   183→                return false;
   184→            }
   185→        }
   186→
   187→        self.current_size += line.size;
   188→
   189→        self.cache_lines
   190→            .entry(line.filename.clone())
   191→            .or_insert_with(Vec::new)
   192→            .push(line);
   193→
   194→        self.dma_transfers += 1;
   195→        true
   196→    }
   197→
   198→    /// LRU + 우선순위 기반 eviction
   199→    fn evict_one(&mut self) -> bool {
   200→        let mut victim: Option<(String, usize, usize)> = None;
   201→        let mut min_priority = usize::MAX;
   202→
   203→        for (filename, lines) in &self.cache_lines {
   204→            for (idx, line) in lines.iter().enumerate() {
   205→                // 낮은 우선순위, 접근 적음, 최근 사용 오래됨 → 제거 후보
   206→                let priority = line.dma_size.priority() + line.access_count;
   207→
   208→                if priority < min_priority {
   209→                    min_priority = priority;
   210→                    victim = Some((filename.clone(), idx, line.size));
   211→                }
   212→            }
   213→        }
   214→
   215→        if let Some((filename, idx, size)) = victim {
   216→            if let Some(lines) = self.cache_lines.get_mut(&filename) {
   217→                if idx < lines.len() {
   218→                    lines.remove(idx);
   219→                    self.current_size = self.current_size.saturating_sub(size);
   220→                    self.eviction_count += 1;
   221→                    return true;
   222→                }
   223→            }
   224→        }
   225→
   226→        false
   227→    }
   228→
   229→    /// DMA 전송 최적화
   230→    pub fn optimize_dma_transfer(&self, size: usize) -> (usize, f64) {
   231→        let dma_size = DMASize::from_bytes(size);
   232→        let efficiency = dma_size.dma_efficiency();
   233→        (dma_size.priority(), efficiency)
   234→    }
   235→
   236→    /// 캐시 일관성 (간단한 write-through)
   237→    pub fn invalidate(&mut self, filename: &str) {
   238→        if let Some(lines) = self.cache_lines.get_mut(filename) {
   239→            let total_size: usize = lines.iter().map(|l| l.size).sum();
   240→            self.current_size = self.current_size.saturating_sub(total_size);
   241→            lines.clear();
   242→        }
   243→    }
   244→
   245→    /// 통계
   246→    pub fn statistics(&self) -> CacheStatistics {
   247→        let total_accesses = self.hit_count + self.miss_count;
   248→        let hit_rate = if total_accesses > 0 {
   249→            self.hit_count as f64 / total_accesses as f64
   250→        } else {
   251→            0.0
   252→        };
   253→
   254→        CacheStatistics {
   255→            hit_count: self.hit_count,
   256→            miss_count: self.miss_count,
   257→            hit_rate,
   258→            total_size: self.current_size,
   259→            prefetch_buffer_used: self.prefetch_buffer_used,
   260→            eviction_count: self.eviction_count,
   261→            dma_transfers: self.dma_transfers,
   262→            utilization: self.current_size as f64 / self.max_size as f64,
   263→        }
   264→    }
   265→}
   266→
   267→/// 캐시 통계
   268→#[derive(Clone, Debug)]
   269→pub struct CacheStatistics {
   270→    pub hit_count: usize,
   271→    pub miss_count: usize,
   272→    pub hit_rate: f64,
   273→    pub total_size: usize,
   274→    pub prefetch_buffer_used: usize,
   275→    pub eviction_count: usize,
   276→    pub dma_transfers: usize,
   277→    pub utilization: f64,
   278→}
   279→
   280→/// 프리페치 버퍼 관리자
   281→#[derive(Clone, Debug)]
   282→pub struct PrefetchBuffer {
   283→    pub pending_requests: Vec<(String, f64)>,  // (filename, confidence)
   284→    pub max_pending: usize,
   285→    pub batch_size: usize,
   286→}
   287→
   288→impl PrefetchBuffer {
   289→    pub fn new(max_pending: usize, batch_size: usize) -> Self {
   290→        PrefetchBuffer {
   291→            pending_requests: Vec::new(),
   292→            max_pending,
   293→            batch_size,
   294→        }
   295→    }
   296→
   297→    /// 프리페치 요청 추가
   298→    pub fn add_request(&mut self, filename: String, confidence: f64) -> bool {
   299→        if self.pending_requests.len() >= self.max_pending {
   300→            return false;  // 버퍼 가득 참
   301→        }
   302→
   303→        self.pending_requests.push((filename, confidence));
   304→        self.pending_requests.sort_by(|a, b| b.1.partial_cmp(&a.1).unwrap());
   305→
   306→        true
   307→    }
   308→
   309→    /// 배치 처리 (상위 batch_size개)
   310→    pub fn get_batch(&mut self) -> Vec<(String, f64)> {
   311→        let batch_size = self.batch_size.min(self.pending_requests.len());
   312→        self.pending_requests.drain(0..batch_size).collect()
   313→    }
   314→
   315→    /// 버퍼 현황
   316→    pub fn pending_count(&self) -> usize {
   317→        self.pending_requests.len()
   318→    }
   319→}
